   wgt=f'exp(-ln(2.0)*x.dd/{name[2:]}.0)';ag += [f'list_sum(list_transform({w},lambda x: x.p*{wgt}))/nullif(list_sum(list_transform({w},lambda x: {wgt})),0) {name}']
  else:
